from pathlib import Path
import json,html
P=Path(__file__).resolve().parent;games=json.loads((P/'games.json').read_text());models=json.loads((P/'games/state-model.json').read_text());M={m['id']:m for m in models}
style='''@font-face{font-family:Inter;src:url('/node-server/public/assets/fonts/inter-variable.ttf')}*{box-sizing:border-box}body{background:#071923;color:#edf4e4;font:14px/1.6 Inter,Arial,sans-serif;margin:0}header{padding:24px 32px;border-bottom:1px solid #36515a;display:flex;gap:20px;align-items:center}a{color:#cbef91}h1{font-size:34px;letter-spacing:-1px;line-height:1.2}h2{font-size:22px}p{color:#b5c7c7}main{padding:24px 32px;max-width:1540px;margin:auto}nav{display:flex;flex-wrap:wrap;gap:16px}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:20px}.card{padding:14px;border:1px solid #3e6267;background:#0e2935;border-radius:15px}.card img{width:100%;border-radius:9px}.card h2{margin:8px 0}label{display:inline-flex;align-items:center;gap:8px}select,button,input{min-height:44px;background:#153542;color:#eef3e4;border:1px solid #688d88;border-radius:8px;padding:9px}button:focus-visible,a:focus-visible,select:focus-visible{outline:3px solid #c4ed88;outline-offset:3px}.tools{display:flex;flex-wrap:wrap;gap:14px;align-items:center;padding:16px 24px;background:#102d39;position:sticky;top:0;z-index:2}#stage{overflow:auto;display:flex;padding:24px;background:#06141d}iframe{border:1px solid #587d76;border-radius:12px;flex:none;margin:auto;background:#0b2532}#receipt{padding:12px 24px;min-height:50px;font:12px/1.6 monospace;background:#102631;color:#d8ebbd;white-space:pre-wrap;overflow-wrap:anywhere}small,.badge{font-size:11px;color:#c7dcae}.compare{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin:20px 0 45px}.compare img{width:100%;border-radius:10px;border:1px solid #45676b}.phone-pair{display:flex;justify-content:center;gap:25px}.phone-pair figure{max-width:390px}.phone-pair img{width:100%}figure{margin:0}figcaption{padding:9px 0;color:#bbcfb8}#state-links{display:flex;gap:8px;flex-wrap:wrap;margin:22px 0}#state-links a{background:#12323c;padding:8px 12px;border-radius:8px}footer{padding:24px 32px;font-size:12px;color:#b5c7c7}@media(max-width:850px){.cards{grid-template-columns:repeat(2,1fr)}header{display:block}main{padding:20px}.compare{display:block}.phone-pair{gap:12px}.tools{position:static}.card h2{font-size:16px}}@media(max-width:450px){.cards{grid-template-columns:1fr}}'''
(P/'review.css').write_text(style)
head=lambda title:f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" href="data:,"><link rel="stylesheet" href="review.css"><title>{title}</title></head><body>'
(P/'index.html').write_text(head('Issue 58 · game feel and Avatar Studio')+'''<header><strong>PLAYGRID / ISSUE 58</strong><span class="badge">Design package · not implemented in production</span></header><main><h1>More feel. More personality.<br>The same Playgrid.</h1><p>20 supported games. 32 new original layered characters. Approved compositions, concrete interaction contracts and reviewable states. Home illustration preserved.</p><nav><a href="avatar-studio/index.html">Open Avatar Studio</a><a href="avatar-studio/character-review.html">All 32 characters</a><a href="avatar-studio/studio-desktop.png">Studio desktop screenshot</a><a href="avatar-studio/studio-mobile.png">Studio phone screenshot</a><a href="assets/golf/review.html">18 existing golf holes</a><a href="HANDOFF.md">Implementation handoff</a><a href="VALIDATION.md">Validation & limits</a><a href="playgrid-issue-58-design.zip">Download ZIP</a></nav><h2>Every game, in context.</h2><p>Each card opens a local interaction/state explorer. Compare the actual current client with the approved direction and new feel refinements. Labels distinguish reused approved art from new Issue 58 work.</p><div class="cards">'''+''.join(f'<article class="card"><a href="explorer.html?game={g["id"]}"><img src="review/proposed/{g["id"]}-desktop.png" alt="{g["name"]} approved composition and interaction extension"><h2>{g["name"]}</h2></a><small>{g["states"]} design states · approved source {g["approvedSource"]}</small><p><a href="comparison.html?game={g["id"]}">Current vs proposed</a> · <a href="games/{g["id"]}/AUDIT.md">Audit & acceptance</a></p></article>' for g in games)+'''</div></main><footer>No production code or protocols changed. No RPS direction. No paid AI APIs. New vector character finish is cleaner than the painted canonical hero; review that difference before integration.</footer></body></html>''')
(P/'explorer.html').write_text(head('Local interaction and state explorer')+'''<header><a href="index.html">← Package</a><strong>Local design explorer</strong><small>Fixtures only · no multiplayer connection</small></header><div class="tools"><label>Game <select id="game"></select></label><label>State <select id="state"></select></label><label>Viewport <select id="viewport"><option value="desktop">1440 × 900</option><option value="mobile">390 × 844</option><option value="narrow">360 × 740</option></select></label><a id="raw" target="_blank">Full-size preview</a><a id="audit">Game audit</a></div><div id="receipt" role="status">Controls record local input drafts here. A state change is a separate fixture, never a fabricated server acknowledgement.</div><div id="stage"><iframe title="Game design preview" width="1440" height="900"></iframe></div><script src="review.js"></script></body></html>''')
(P/'comparison.html').write_text(head('Current client vs approved design extension')+'''<header><a href="index.html">← Package</a><strong id="name"></strong><span class="badge">Real browser captures</span></header><main><h1>Compare the same game.</h1><p>Left: unchanged working client at 06609a4. Right: approved visual direction plus Issue 58 local interaction extensions. Fixture players and game positions differ; this comparison evaluates hierarchy, controls and visual finish.</p><div class="compare"><figure><img id="old-d" alt="Current desktop client"><figcaption>Current · 1440 × 900</figcaption></figure><figure><img id="new-d" alt="Proposed desktop design"><figcaption>Proposed design · 1440 × 900</figcaption></figure></div><div class="phone-pair"><figure><img id="old-m" alt="Current mobile client"><figcaption>Current · 390 × 844</figcaption></figure><figure><img id="new-m" alt="Proposed mobile design"><figcaption>Proposed design · 390 × 844</figcaption></figure></div><h2>All major states</h2><p>Each link opens the desktop and phone screenshot pair from the same illustrative state. They are not sequential gameplay captures.</p><div id="state-links"></div></main><script src="comparison.js"></script></body></html>''')
(P/'review.js').write_text('''(async()=>{const games=await fetch('games.json').then(r=>r.json()),models=await fetch('games/state-model.json').then(r=>r.json()),$=id=>document.getElementById(id),game=$('game'),state=$('state'),frame=document.querySelector('iframe');games.forEach(g=>game.add(new Option(g.name,g.id)));game.value=new URLSearchParams(location.search).get('game')||games[0].id;function states(){state.innerHTML='';models.find(g=>g.id===game.value).states.forEach(s=>state.add(new Option(s.label,s.id)));state.value='active';render();}function render(){const url='games/'+game.value+'/index.html?state='+state.value;frame.src=url;const dims={desktop:[1440,900],mobile:[390,844],narrow:[360,740]}[$('viewport').value];frame.width=dims[0];frame.height=dims[1];$('raw').href=url;$('audit').href='games/'+game.value+'/AUDIT.md';$('receipt').textContent='Local fixture: '+game.value+' / '+state.value+'. No action sent.';history.replaceState(null,'','?game='+game.value);}game.onchange=states;state.onchange=render;$('viewport').onchange=render;window.addEventListener('message',e=>{if(e.origin===location.origin&&e.source===frame.contentWindow&&e.data.type==='playgrid-design-draft')$('receipt').textContent=JSON.stringify(e.data,null,2)+'\\nLocal design draft only. Current state has not advanced.';});states();})()''')
(P/'comparison.js').write_text('''(async()=>{const games=await fetch('games.json').then(r=>r.json()),id=new URLSearchParams(location.search).get('game')||games[0].id,g=games.find(g=>g.id===id)||games[0],models=await fetch('games/state-model.json').then(r=>r.json());document.getElementById('name').textContent=g.name;for(const [s,type]of[['d','desktop'],['m','mobile']]){document.getElementById('old-'+s).src='review/current-client/'+g.id+'-'+type+'.png';document.getElementById('new-'+s).src='review/proposed/'+g.id+'-'+type+'.png';}models.find(m=>m.id===g.id).states.forEach(s=>{const a=document.createElement('a');a.textContent=s.label;a.href='review/states/'+g.id+'/'+s.id+'.html';document.getElementById('state-links').append(a);});})()''')
print('20-game gallery and state/interaction explorer built.')
